const KEY = 'launchready-demo-v1';
const seed = {
  goal: 'Can first-time players find the first checkpoint without help?',
  seen: false,
  feedback: [
    {id:1,stage:'First minute',theme:'Wayfinding',title:'I could not spot the first checkpoint',detail:'The glowing arch looked decorative, so I ran past the route.',severity:'High',status:'Open',votes:3},
    {id:2,stage:'Join',theme:'Performance',title:'Loaded into a grey screen on mobile',detail:'The scene appeared after a long wait on my phone.',severity:'High',status:'Open',votes:2},
    {id:3,stage:'Core loop',theme:'Difficulty',title:'The second jump feels too punishing',detail:'I repeated it several times before I understood the timing.',severity:'Medium',status:'Open',votes:2},
    {id:4,stage:'First minute',theme:'Wayfinding',title:'A small arrow would help',detail:'I understood the level after a friend pointed me toward the checkpoint.',severity:'Medium',status:'Open',votes:1},
    {id:5,stage:'Return intent',theme:'Motivation',title:'I want to try again with a friend',detail:'The race to the finish was the most fun part.',severity:'Low',status:'Captured',votes:1}
  ],
  checks:[
    {id:'prompt',title:'Playtest question is specific',help:'Ask testers about a concrete moment, not whether they liked the game.',done:true},
    {id:'triage',title:'Critical feedback is triaged',help:'Every high severity issue has an owner or a decision.',done:false},
    {id:'first',title:'First minute friction is addressed',help:'A new player can find the core action without outside help.',done:false},
    {id:'devices',title:'Mobile and desktop pass reviewed',help:'Check load, controls, and performance on both device types.',done:false},
    {id:'safety',title:'Safety and audience settings reviewed',help:'Confirm applicable Roblox requirements in Creator Hub.',done:false},
    {id:'measure',title:'Post-launch measures defined',help:'Choose a primary metric, guardrails, and a review date.',done:true}
  ],
  priorities:[
    {id:'wayfinding',name:'Make the first checkpoint unmistakable',reach:7,impact:3,confidence:70,effort:2},
    {id:'mobile',name:'Investigate slow mobile load',reach:5,impact:3,confidence:60,effort:3},
    {id:'jump',name:'Tune the second jump',reach:4,impact:2,confidence:65,effort:2},
    {id:'social',name:'Add a friend race prompt',reach:3,impact:1,confidence:45,effort:4}
  ]
};
const copy = x => JSON.parse(JSON.stringify(x));
let state;
try { state = {...copy(seed), ...JSON.parse(localStorage.getItem(KEY) || '{}')}; } catch {state = copy(seed)}
let view = 'overview', search = '', filter = 'All';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save = () => localStorage.setItem(KEY, JSON.stringify(state));
const toast = msg => { const el=$('#toast'); el.textContent=msg; el.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>el.classList.remove('show'),2600) };
const score = p => Math.round((p.reach * p.impact * p.confidence / 100 / p.effort)*10)/10;
const readiness = () => Math.round(state.checks.filter(c=>c.done).length/state.checks.length*100);
const openHigh = () => state.feedback.filter(f=>f.severity==='High' && f.status!=='Resolved').length;
const tagClass = t => ({High:'coral',Medium:'yellow',Low:'teal',Wayfinding:'coral',Performance:'yellow',Motivation:'teal'}[t] || '');
const tag = t => `<span class="tag ${tagClass(t)}">${esc(t)}</span>`;
function setView(next){view=next; document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===next)); render(); window.scrollTo({top:0,behavior:'smooth'})}
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subhead">${sub}</p></div>${action}</div>`}
function foot(){return `<footer class="footer">Independent concept by Amulya Ravikumar · All sample data is synthetic · <a href="https://devforum.roblox.com/t/a-simpler-path-to-publish-plus-invite-early-testers/4930524" target="_blank" rel="noreferrer">Roblox announcement ↗</a><a href="https://create.roblox.com/docs/production/experiments" target="_blank" rel="noreferrer">Creator experiments docs ↗</a></footer>`}
function overview(){const done=state.checks.filter(c=>c.done).length;return `<section class="page">${heading('THE PLAYTEST DESK','A clearer path from feedback to launch','A small tester group can reveal big friction. This workspace helps a creator decide what to fix, what to watch, and when to ship.')}
<div class="hero"><div><div class="tiny-label">YOUR PLAYTEST QUESTION</div><h2>${esc(state.goal)}</h2><p>Start with a real question. Trace feedback to a moment in the player journey, then make a visible decision.</p><button class="button" data-go="feedback">Review feedback →</button></div><div class="hero-right"><small>LAUNCH READINESS</small><strong>${readiness()}%</strong><p>${done} of ${state.checks.length} checks complete. ${openHigh()} high severity issue${openHigh()===1?'':'s'} still open.</p></div></div>
<div class="grid metrics"><div class="metric"><label>TESTER INVITES</label><strong>8 / 10</strong><small>Synthetic scenario · not connected</small><div class="spark"><i style="width:80%"></i></div></div><div class="metric"><label>FEEDBACK SIGNALS</label><strong>${state.feedback.length}</strong><small>Added in this demo workspace</small><div class="spark"><i style="width:${Math.min(100,state.feedback.length*12)}%"></i></div></div><div class="metric"><label>OPEN HIGH SEVERITY</label><strong>${openHigh()}</strong><small>Needs a decision before launch</small><div class="spark"><i style="width:${Math.min(100,openHigh()*28)}%;background:#ff9d86"></i></div></div><div class="metric"><label>CHECKS COMPLETE</label><strong>${done} / ${state.checks.length}</strong><small>Creator-owned checklist</small><div class="spark"><i style="width:${readiness()}%;background:#6fd2c8"></i></div></div></div>
<div class="grid main-grid"><div class="panel"><div class="panel-title"><h3>Where the first session bends</h3><button data-go="journey">Explore journey →</button></div>${journeyBars()}<div class="insight"><span class="icon">✧</span><span><b>Hypothesis to test:</b> clearer checkpoint cues may reduce first-minute confusion. These bars are illustrative, not measured player analytics.</span></div></div><div class="panel"><div class="panel-title"><h3>Signals to act on</h3><button data-go="feedback">Open inbox →</button></div>${state.feedback.filter(f=>f.status!=='Resolved').slice(0,3).map(f=>`<div class="signal">${tag(f.theme)}<p>${esc(f.title)}</p><small>${esc(f.stage)} · ${f.votes} supporting signal${f.votes===1?'':'s'}</small></div>`).join('')||'<p>No open signals.</p>'}</div></div>${foot()}</section>`}
function journeyBars(){return [['Join',92,''],['First minute',64,'coral'],['Core loop',78,'cyan'],['Return intent',48,'lime']].map(([name,n,c])=>`<div class="stage-row"><b>${name}</b><div class="bar ${c}"><i style="width:${n}%"></i></div><small>${n}%</small></div>`).join('')}
function feedback(){let list=state.feedback.filter(f=>(filter==='All'||f.status===filter||f.severity===filter||f.theme===filter) && [f.title,f.detail,f.theme,f.stage].join(' ').toLowerCase().includes(search.toLowerCase()));return `<section class="page">${heading('LISTEN → ORGANIZE → DECIDE','Feedback inbox','Capture an observation, attach it to a journey moment, and make the next action explicit.',`<button id="toggleForm" class="button button-primary">+ Add feedback</button>`)}<div class="panel" id="feedbackForm" hidden><div class="panel-title"><h3>Add a synthetic playtest note</h3></div><form id="addForm" class="form-grid"><label class="wide">What happened?<input class="input" name="title" maxlength="100" required placeholder="e.g. I missed the first checkpoint"></label><label class="wide">What did the tester say or do?<textarea class="textarea" name="detail" maxlength="300" required></textarea></label><label>Journey moment<select class="select" name="stage"><option>Join</option><option>First minute</option><option>Core loop</option><option>Return intent</option></select></label><label>Theme<select class="select" name="theme"><option>Wayfinding</option><option>Performance</option><option>Difficulty</option><option>Motivation</option><option>Other</option></select></label><label>Severity<select class="select" name="severity"><option>Medium</option><option>High</option><option>Low</option></select></label><div style="align-self:end"><button class="button button-dark" type="submit">Save feedback</button></div></form></div><div class="section-spacer"></div><div class="toolbar"><input id="searchInput" class="input search" type="search" placeholder="Search feedback..." value="${esc(search)}" aria-label="Search feedback"><select id="filterSelect" class="select" aria-label="Filter feedback">${['All','Open','Captured','Resolved','High','Medium','Low','Wayfinding','Performance','Difficulty','Motivation'].map(o=>`<option ${filter===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="feedback-list">${list.map(f=>`<article class="feedback-card" data-search="${esc([f.title,f.detail,f.theme,f.stage].join(' ').toLowerCase())}"><div>${tag(f.theme)} ${tag(f.severity)}<h3>${esc(f.title)}</h3><p>${esc(f.detail)}</p><small>${esc(f.stage)} · ${esc(f.status)} · Synthetic playtest note</small></div><div class="feedback-actions"><button data-vote="${f.id}" aria-label="Add supporting signal for ${esc(f.title)}">＋ ${f.votes}</button><select data-status="${f.id}" aria-label="Status for ${esc(f.title)}">${['Open','Captured','Resolved'].map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select></div></article>`).join('')||'<div class="panel">No feedback matches this filter.</div>'}</div>${foot()}</section>`}
function journey(){const stages=[['Join','Can they enter smoothly?','Load, spawn, control affordances'],['First minute','Can they find the fun?','Wayfinding, first action, clarity'],['Core loop','Can they keep going?','Difficulty, pacing, rewards'],['Return intent','Would they come back?','Social pull, goals, replay value']];return `<section class="page">${heading('OBSERVE THE MOMENT','Player journey','Group qualitative signals by the moment they occur. The percentages below are illustrative placeholders, not observed conversion rates.')}<div class="grid journey-grid">${stages.map(([name,q,desc],i)=>`<div class="journey-card"><span class="number">0${i+1}</span><h3>${name}</h3><p><b>${q}</b><br>${desc}</p><strong>${state.feedback.filter(f=>f.stage===name).length}</strong><small>synthetic notes</small></div>`).join('')}</div><div class="section-spacer"></div><div class="grid main-grid"><div class="panel"><div class="panel-title"><h3>Illustrative first-session path</h3></div>${journeyBars()}<div class="insight"><span class="icon">ⓘ</span><span>A real version would need instrumented events and a defined denominator. These values only show a proposed view.</span></div></div><div class="panel"><div class="panel-title"><h3>Creator interview prompt</h3></div><p style="font-size:17px;font-weight:700">“Show me the first moment a player needed help.”</p><p class="subhead">Ask the creator to replay the moment, then ask what they expected the player to do. Do not turn this prototype’s synthetic notes into claimed research.</p></div></div>${foot()}</section>`}
function priorities(){const sorted=[...state.priorities].sort((a,b)=>score(b)-score(a));return `<section class="page">${heading('TRADEOFFS, MADE VISIBLE','Priorities','A directional RICE-style score helps compare ideas. Inputs are illustrative and should be revised with actual reach and effort evidence.')}<div class="priority-wrap panel" style="padding:0"><table class="priority-table"><thead><tr><th>Opportunity</th><th>Reach / 10</th><th>Impact / 3</th><th>Confidence %</th><th>Effort</th><th>Score</th></tr></thead><tbody>${sorted.map(p=>`<tr><td>${esc(p.name)}</td>${[['reach',1,10],['impact',1,3],['confidence',1,100],['effort',1,10]].map(([field,min,max])=>`<td><input type="number" data-priority="${p.id}" data-field="${field}" min="${min}" max="${max}" value="${p[field]}" aria-label="${field} for ${esc(p.name)}"></td>`).join('')}<td class="score">${score(p)}</td></tr>`).join('')}</tbody></table></div><div class="section-spacer"></div><div class="grid main-grid"><div class="panel"><h3>Why the first checkpoint comes first</h3><p class="subhead">The concept centers on first-session comprehension: a creator can make a small, reversible cue change and ask the next testers whether they find the checkpoint without help. This is a hypothesis, not a validated finding.</p></div><div class="panel"><h3>Scoring rule</h3><p class="subhead">Reach × Impact × Confidence ÷ Effort. The units are normalized for a small concept exercise; scores are only comparable within this table.</p></div></div>${foot()}</section>`}
function readinessPage(){const pct=readiness(), unresolved=openHigh();return `<section class="page">${heading('A DECISION, NOT A BADGE','Launch readiness','The checklist records a creator decision. It does not replace Roblox eligibility, safety review, or publishing controls.')}<div class="grid readiness-layout"><div><div class="readiness-score"><div class="tiny-label" style="color:#b5f4e8">CURRENT SNAPSHOT</div><strong>${pct}%</strong><p>${state.checks.filter(c=>c.done).length} of ${state.checks.length} checks complete</p><div class="bar"><i style="width:${pct}%;background:#a9ede2"></i></div></div><div class="section-spacer"></div><div class="warning">${unresolved?`<b>${unresolved} high severity issue${unresolved===1?'':'s'} remain open.</b> Resolve, assign, or consciously defer them before a public launch decision.`:'No high severity issues remain open in this demo.'}</div></div><div class="checklist">${state.checks.map(c=>`<label class="check ${c.done?'done':''}"><input type="checkbox" data-check="${c.id}" ${c.done?'checked':''}><span><b>${esc(c.title)}</b><small>${esc(c.help)}</small></span></label>`).join('')}</div></div>${foot()}</section>`}
function story(){return `<section class="page">${heading('THE PRODUCT THINKING','Why LaunchReady','A proposed companion workflow for creators using Roblox’s new early tester access. Built independently by Amulya Ravikumar.')}<div class="grid story-grid"><div class="story-card"><div class="eyebrow">01 · PROBLEM</div><h3>The test is small. The decision is not.</h3><p>Roblox now permits eligible creators to invite up to 10 early testers before public release. A creator still needs to decide what to ask, how to sort the answers, and what is important enough to fix.</p></div><div class="story-card"><div class="eyebrow">02 · PRODUCT</div><h3>Make every signal actionable</h3><p>LaunchReady links a playtest question to player moments, triage, priorities, and a transparent launch checklist. The MVP is intentionally lightweight for a first-time creator.</p></div><div class="story-card"><div class="eyebrow">03 · LEARNING</div><h3>Measure the workflow</h3><p>North star proposal: the share of creators who complete a playtest and record a justified launch decision. Guardrails include safety completion, unresolved critical issues, and creator time spent.</p></div></div><div class="section-spacer"></div><div class="panel"><div class="panel-title"><h3>Source-grounded, clearly bounded</h3></div><p class="subhead">This is a portfolio concept. No creator interviews, live Roblox integration, measured impact, or A/B test results are claimed. Roblox’s guided publishing rollout may vary by creator. Use the linked announcement and documentation for the current platform rules.</p><div style="margin-top:18px;display:flex;gap:12px;flex-wrap:wrap"><a class="button button-primary" href="case-study.html">Read full case study →</a><a class="button button-light" href="https://devforum.roblox.com/t/a-simpler-path-to-publish-plus-invite-early-testers/4930524" target="_blank" rel="noreferrer">October announcement ↗</a><a class="button button-light" href="https://create.roblox.com/docs/production/analytics/engagement" target="_blank" rel="noreferrer">Engagement guidance ↗</a><a class="button button-light" href="https://create.roblox.com/docs/production/experiments" target="_blank" rel="noreferrer">Experiments docs ↗</a></div></div>${foot()}</section>`}
function render(){const views={overview,feedback,journey,priorities,readiness:readinessPage,story};$('#content').innerHTML=views[view]();}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return}const go=e.target.closest('[data-go]');if(go){setView(go.dataset.go);return}const vote=e.target.closest('[data-vote]');if(vote){const f=state.feedback.find(x=>x.id===Number(vote.dataset.vote));if(f){f.votes++;save();render();toast('Supporting signal added')}return}if(e.target.id==='toggleForm'){$('#feedbackForm').hidden=!$('#feedbackForm').hidden;return}if(e.target.id==='resetBtn'){if(confirm('Restore all synthetic demo data and clear your browser edits?')){state=copy(seed);state.seen=true;save();setView('overview');toast('Demo restored')}return}if(e.target.id==='exportBtn'){const rows=[['Title','Detail','Stage','Theme','Severity','Status','Signals'],...state.feedback.map(f=>[f.title,f.detail,f.stage,f.theme,f.severity,f.status,f.votes])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='launchready-synthetic-feedback.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Synthetic feedback exported')}});
document.addEventListener('change',e=>{const status=e.target.closest('[data-status]');if(status){const f=state.feedback.find(x=>x.id===Number(status.dataset.status));if(f){f.status=status.value;save();render();toast('Status updated')}return}const check=e.target.closest('[data-check]');if(check){const c=state.checks.find(x=>x.id===check.dataset.check);if(c){c.done=check.checked;save();render();toast('Checklist updated')}return}const pri=e.target.closest('[data-priority]');if(pri){const p=state.priorities.find(x=>x.id===pri.dataset.priority);const field=pri.dataset.field;const min=Number(pri.min),max=Number(pri.max);if(p){p[field]=Math.max(min,Math.min(max,Number(pri.value)||min));pri.value=p[field];save();pri.closest('tr').querySelector('.score').textContent=score(p);toast('Priority recalculated')}return}if(e.target.id==='filterSelect'){filter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){search=e.target.value;document.querySelectorAll('.feedback-card').forEach(card=>{card.hidden=!card.dataset.search.includes(search.toLowerCase())})}});
document.addEventListener('submit',e=>{if(e.target.id!=='addForm')return;e.preventDefault();const data=new FormData(e.target);state.feedback.unshift({id:Date.now(),title:String(data.get('title')).trim(),detail:String(data.get('detail')).trim(),stage:data.get('stage'),theme:data.get('theme'),severity:data.get('severity'),status:'Open',votes:1});save();render();toast('Feedback added')});
$('#beginBtn').addEventListener('click',()=>{state.goal=$('#goalInput').value.trim()||seed.goal;state.seen=true;save();render()});
render();if(!state.seen) $('#onboarding').showModal();
